import{_ as s,r as i,o as l,c as d,a as t,b as o,d as r,e as n}from"./chunks/framework.8NMv9ABN.js";const v=JSON.parse('{"title":"Monitor","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/monitor.md","filePath":"en/tools/monitor.md"}'),h={name:"en/tools/monitor.md"};function c(g,e,u,m,p,f){const a=i("Screenshot");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"monitor",tabindex:"-1"},[o("Monitor "),t("a",{class:"header-anchor",href:"#monitor","aria-label":'Permalink to "Monitor"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("Monitor ranks the whole market by a volatility metric and keeps the top of that ranking on screen. Where "),t("a",{href:"/manual/en/tools/knives.html"},"Knives"),o(" waits for something to cross a line and then tells you, Monitor is a continuously sorted leaderboard.")],-1)),e[2]||(e[2]=t("p",null,[o("All readings are based on "),t("strong",null,"5-minute candles"),o(".")],-1)),r(a,{src:"monitor",alt:"The Monitor window showing ranked ticker cards",caption:"The Monitor window"}),e[3]||(e[3]=n('<h2 id="reading-the-window" tabindex="-1">Reading the window <a class="header-anchor" href="#reading-the-window" aria-label="Permalink to &quot;Reading the window&quot;">​</a></h2><h3 id="titlebar" tabindex="-1">Titlebar <a class="header-anchor" href="#titlebar" aria-label="Permalink to &quot;Titlebar&quot;">​</a></h3><p>The titlebar is a live summary of the settings currently in effect:</p><ul><li><strong>5m</strong> — the candle timeframe. Fixed.</li><li><strong>NATR | Vol | Chg</strong> — the active sort. These are buttons: click to re-sort without opening settings.</li><li><strong>Sort detail</strong> — what the current sort is doing. For NATR it shows the smoothing method and aggregation mode (e.g. <code>SMA · Weighted</code>); for Volume, the source and type (e.g. <code>Total · 75m</code>); for % Change, just <code>% Change</code>. If a minimum volume filter is active it is appended as <code>min $&lt;amount&gt;</code>.</li><li><strong>Alert thresholds</strong> — <code>NATR ≥x% · % ≥y%</code>. Dimmed when the alert sound is off.</li><li><strong>Exchange icons</strong> — the enabled exchanges, in priority order.</li><li><strong>Disconnected</strong> — shown if the data connection drops.</li></ul><h3 id="a-ticker-card" tabindex="-1">A ticker card <a class="header-anchor" href="#a-ticker-card" aria-label="Permalink to &quot;A ticker card&quot;">​</a></h3><p>Each card shows the ticker, the exchanges it is listed on, and three metrics:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>NATR</strong></td><td>Volatility — normalised average true range, on 5m candles</td></tr><tr><td><strong>Volume</strong></td><td>Trading volume in USD, over the window set by <a href="#volume-type">Volume type</a></td></tr><tr><td><strong>% Change</strong></td><td>Price change over 5m</td></tr></tbody></table><p>Hovering an exchange logo reads <code>Listed on &lt;exchange&gt;</code>. Cards have an expand button that opens a fullscreen chart with the same drawing tools as the <a href="/manual/en/tools/analyzer.html#drawing-tools">Analyzer</a>.</p><h3 id="what-the-colors-mean" tabindex="-1">What the colors mean <a class="header-anchor" href="#what-the-colors-mean" aria-label="Permalink to &quot;What the colors mean&quot;">​</a></h3><p>Coloring is driven by the <a href="#metric-colors">metric color</a> rules, which are independent of the alert thresholds:</p><ul><li><strong>NATR</strong> shifts from its level-1 color to its level-2 color as volatility rises past each level.</li><li><strong>% Change</strong> is colored by direction — one pair of colors for positive moves, another for negative — and also steps up at level 2.</li></ul><p>If dynamic colors are switched off for a metric, that metric instead highlights plainly when it crosses its <strong>alert threshold</strong>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open the <strong>Monitor</strong> tab in the main window.</p>',14)),r(a,{src:"monitor-settings",alt:"Monitor sorting settings",caption:"Monitor settings — sorting"}),e[4]||(e[4]=n('<h3 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h3><h4 id="sort-by" tabindex="-1">Sort by <a class="header-anchor" href="#sort-by" aria-label="Permalink to &quot;Sort by&quot;">​</a></h4><p>Which metric ranks the list: <strong>NATR</strong>, <strong>Volume</strong> or <strong>% Change</strong>. Default NATR.</p><h4 id="natr-method" tabindex="-1">NATR method <a class="header-anchor" href="#natr-method" aria-label="Permalink to &quot;NATR method&quot;">​</a></h4><p>The smoothing algorithm used to calculate NATR. Default <strong>SMA</strong>.</p><ul><li><strong>RMA</strong> — Wilder&#39;s moving average. Smoother, slower to react.</li><li><strong>SMA</strong> — simple moving average. More responsive to recent candles.</li></ul><h4 id="natr-aggregation" tabindex="-1">NATR aggregation <a class="header-anchor" href="#natr-aggregation" aria-label="Permalink to &quot;NATR aggregation&quot;">​</a></h4><p>How one NATR figure is produced for a ticker listed on several exchanges. Default <strong>Weighted</strong>.</p><ul><li><strong>Weighted</strong> — volume-weighted average across exchanges.</li><li><strong>Highest</strong> — the maximum NATR across all exchanges.</li><li><strong>Priority</strong> — the value from the first exchange in your priority order that has data for that ticker.</li></ul><h4 id="volume-source" tabindex="-1">Volume source <a class="header-anchor" href="#volume-source" aria-label="Permalink to &quot;Volume source&quot;">​</a></h4><p>Where the volume figure comes from. Default <strong>Total</strong>.</p><ul><li><strong>Total</strong> — turnover summed across all enabled exchanges.</li><li><strong>Priority</strong> — turnover from the first exchange in priority order only.</li></ul><h4 id="volume-type" tabindex="-1">Volume type <a class="header-anchor" href="#volume-type" aria-label="Permalink to &quot;Volume type&quot;">​</a></h4><p>Which window the volume figure covers. Default <strong>75m</strong>.</p><ul><li><strong>75m</strong> — 75-minute rolling volume.</li><li><strong>5m</strong> — the current 5-minute candle&#39;s volume.</li></ul><div class="warning custom-block"><p class="custom-block-title">This setting also picks which volume filter is live</p><p>Monitor has two minimum-volume sliders, and <strong>only the one matching the current Volume type does anything</strong>:</p><ul><li>Volume type <strong>75m</strong> → the <strong>Min volume (75m)</strong> slider filters the list.</li><li>Volume type <strong>5m</strong> → the <strong>Min volume (5m)</strong> slider filters the list.</li></ul><p>The other slider keeps its value but is inert. If you set a filter and see no effect, check that Volume type matches the slider you moved. The titlebar&#39;s <code>min $…</code> readout always shows the one actually in force.</p></div><h4 id="min-volume-75m" tabindex="-1">Min volume (75m) <a class="header-anchor" href="#min-volume-75m" aria-label="Permalink to &quot;Min volume (75m)&quot;">​</a></h4><p>Excludes tickers below this 75-minute volume. Range <strong>$0 to $100M</strong> in $1M steps, default 0 — displayed as <code>None</code>, meaning no filtering.</p><h4 id="min-volume-5m" tabindex="-1">Min volume (5m) <a class="header-anchor" href="#min-volume-5m" aria-label="Permalink to &quot;Min volume (5m)&quot;">​</a></h4><p>Excludes tickers below this 5-minute candle volume. Range <strong>$0 to $10M</strong> in $100K steps, default 0 (<code>None</code>).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>How many ticker cards to display. Range <strong>3 to 30</strong>, default 12. The list re-ranks live as you change it.</p><h3 id="metric-colors" tabindex="-1">Metric colors <a class="header-anchor" href="#metric-colors" aria-label="Permalink to &quot;Metric colors&quot;">​</a></h3><p>Two metrics have configurable dynamic colors: <strong>NATR</strong> and <strong>% Change</strong>. Each has a master toggle, two thresholds, and colors for text, outline and background.</p><h4 id="natr-color" tabindex="-1">NATR color <a class="header-anchor" href="#natr-color" aria-label="Permalink to &quot;NATR color&quot;">​</a></h4><p>Master switch for NATR&#39;s dynamic coloring. On by default. Off makes NATR use the plain highlight-on-alert-threshold behaviour instead.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Range</th><th>Default</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>NATR above this uses color 1</td><td>1–10%, 0.5 steps</td><td>3% (<code>#A082E8</code>)</td></tr><tr><td><strong>Level 2 threshold</strong></td><td>NATR above this uses color 2</td><td>1.5–10%, 0.5 steps</td><td>effective 7% (<code>#FFA040</code>)</td></tr><tr><td><strong>Outline</strong></td><td>Border color per level, plus an on/off toggle</td><td>—</td><td>off</td></tr><tr><td><strong>Background</strong></td><td>Fill color per level, plus an on/off toggle</td><td>—</td><td>off</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Level 2 is additive</p><p>The value shown next to the Level 2 slider is <strong>Level 1 + Level 2</strong>, not the slider&#39;s own value. With Level 1 at 3% and the Level 2 slider at 4%, the label reads <strong>7.0%</strong> — that is where color 2 actually starts.</p><p>The same is true of the % Change level 2 slider. Read the label, not the slider.</p></div><p>Outline and background are separate toggles with their own level-1 and level-2 colors, so you can have colored text only, a colored border, a filled card, or any combination.</p><div class="tip custom-block"><p class="custom-block-title">Every one of these can be translucent</p><p>All fourteen color slots here use the same picker as the rest of the app, and it has an opacity slider. Opacity is stored inside the hex, so a translucent value reads as 8 digits (<code>#rrggbbaa</code>) rather than 6 — see <a href="/manual/en/customize/chart-colors.html#the-color-picker">the color picker</a>.</p><p>Background fills are where this matters most: at full opacity a filled card hides the row underneath it, while something around 15–25% tints it instead.</p></div><h4 id="change-direction" tabindex="-1">% Change direction <a class="header-anchor" href="#change-direction" aria-label="Permalink to &quot;% Change direction&quot;">​</a></h4><p>Master switch for % Change&#39;s dynamic coloring. On by default.</p><p>It works like NATR but with <strong>two colors per level</strong> — one for positive moves, one for negative:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>Default</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>1–10%, 0.5 steps</td><td>2% — positive <code>#4CAF50</code>, negative <code>#E05555</code></td></tr><tr><td><strong>Level 2 threshold</strong></td><td>1.5–10%, 0.5 steps</td><td>effective 5% — positive <code>#00E676</code>, negative <code>#FF5252</code></td></tr><tr><td><strong>Outline</strong></td><td>—</td><td>off</td></tr><tr><td><strong>Background</strong></td><td>—</td><td>off</td></tr></tbody></table><h3 id="exchange-icons" tabindex="-1">Exchange icons <a class="header-anchor" href="#exchange-icons" aria-label="Permalink to &quot;Exchange icons&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Shows or hides the exchange logos on ticker cards. On by default.</p><h3 id="exchanges" tabindex="-1">Exchanges <a class="header-anchor" href="#exchanges" aria-label="Permalink to &quot;Exchanges&quot;">​</a></h3><p>A single drag-to-reorder list handles both priority and enablement, split by a divider:</p><ul><li><strong>Above the divider</strong> — enabled, numbered by rank. Rank matters for the <code>Priority</code> options in NATR aggregation and Volume source.</li><li><strong>Below the divider</strong> — disabled. Their rank shows as <code>—</code> and they contribute no data.</li></ul><p>Drag an exchange across the divider to enable or disable it. All five are enabled by default, in the order <strong>Binance, Bybit, OKX, Gate.io, Hyperliquid</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Monitor&#39;s default priority order differs from Knives&#39; (<code>Bybit, Binance, Gate.io, OKX, Hyperliquid</code>). The two tools keep separate priority lists — reordering one does not affect the other.</p></div><h3 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Plays a sound when a ticker meets the NATR or % Change threshold below. On by default. When off, the titlebar&#39;s threshold readout is dimmed.</p><h4 id="natr-threshold" tabindex="-1">NATR threshold <a class="header-anchor" href="#natr-threshold" aria-label="Permalink to &quot;NATR threshold&quot;">​</a></h4><p>Highlights and alerts when NATR exceeds this percentage. Range <strong>3% to 20%</strong> in 0.5% steps, default 5%.</p><h4 id="change-threshold" tabindex="-1">% Change threshold <a class="header-anchor" href="#change-threshold" aria-label="Permalink to &quot;% Change threshold&quot;">​</a></h4><p>Highlights and alerts when % change exceeds this. Range <strong>3% to 20%</strong> in 0.5% steps, default 4%.</p><div class="info custom-block"><p class="custom-block-title">Thresholds and colors are separate systems</p><p>The alert thresholds here decide when a <em>sound</em> fires. The <a href="#metric-colors">metric color</a> levels decide how a value is <em>drawn</em>. They are configured independently and can be set to different values — a card can be colored without having triggered a sound, and vice versa.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/tools/knives.html">Knives</a> — trigger-based feed rather than a ranking</li><li><a href="/manual/en/tools/analyzer.html">Analyzer</a> — full chart workspace</li><li><a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> — candle colors used by Monitor&#39;s charts</li></ul>',53))])}const y=s(h,[["render",c]]);export{v as __pageData,y as default};
